#include <stdlib.h>
#include <string.h>

char *join(const char *const *parts, size_t n, const char *sep)
{
    size_t sep_len = strlen(sep);
    size_t total = 1;
    for (size_t i = 0; i < n; i++) total += strlen(parts[i]) + (i ? sep_len : 0);
    char *out = malloc(total);
    if (!out) return NULL;
    char *p = out;
    for (size_t i = 0; i < n; i++) {
        if (i) {
            memcpy(p, sep, sep_len);
            p += sep_len;
        }
        size_t len = strlen(parts[i]);
        memcpy(p, parts[i], len);
        p += len;
    }
    *p = '\0';
    return out;
}

unitTests:
TEST("three words") { const char *w[] = {"tea", "cake", "milk"}; char *s = join(w, 3, ", "); CHECK_STR(s, "tea, cake, milk"); free(s); }
TEST("one word, no separator") { const char *w[] = {"alone"}; char *s = join(w, 1, "-"); CHECK_STR(s, "alone"); free(s); }
TEST("nothing gives an empty string") { char *s = join(NULL, 0, ", "); CHECK(s != NULL); CHECK_STR(s, ""); free(s); }
TEST("empty parts and separators") { const char *w[] = {"", "x", ""}; char *s = join(w, 3, "/"); CHECK_STR(s, "/x/"); free(s); char *t = join(w, 3, ""); CHECK_STR(t, "x"); free(t); }

